<template><section class="checkout"><h1>Checkout</h1><form @submit.prevent="submit"><label>Delivery address<textarea v-model="form.address" required placeholder="Street, city, postal code"></textarea></label><label>Payment method<select v-model="form.paymentMethod"><option>Cash on delivery</option><option>Card (demo)</option><option>UPI (demo)</option></select></label><div class="summary">Order total <strong>Rs.{{ cart.total.toFixed(2) }}</strong></div><p v-if="error" class="error">{{ error }}</p><button class="primary" :disabled="busy">{{ busy ? 'Placing order...' : 'Place order' }}</button></form></section></template>
<script>
import axios from 'axios'; import { useCartStore } from '../stores/cartStore.js'; import { useAuthStore } from '../stores/authStore.js'
export default { data: () => ({ form: { address: '', paymentMethod: 'Cash on delivery' }, busy: false, error: null }), computed: { cart() { return useCartStore() } }, created() { this.cart.fetchCart() }, methods: { async submit() { this.busy=true; this.error=null; try { await axios.post('/api/orders', { ...this.form, userId: useAuthStore().user.id, items: this.cart.items }); for (const item of [...this.cart.items]) await this.cart.removeItem(item.productId); this.$router.push('/orders') } catch(e) { this.error=e.response?.data?.message || e.response?.data?.detail || e.response?.data?.error || 'Checkout failed' } finally { this.busy=false } } } }
</script>
<style scoped>.checkout{max-width:560px;margin:auto;background:#fff;padding:30px;border-radius:14px}.checkout h1{margin-bottom:24px}.checkout form{display:grid;gap:18px}.checkout label{display:grid;gap:8px;font-weight:600}.checkout textarea,.checkout select{padding:12px;border:1px solid #d5dbea;border-radius:7px;font:inherit}.checkout textarea{min-height:100px}.summary{display:flex;justify-content:space-between;font-size:1.15rem;padding:18px 0;border-top:1px solid #eee}.primary{background:#4a00e0;color:#fff;border:0;border-radius:7px;padding:12px}.error{color:#c0392b}</style>
